ARITHMETIC_OPERATORS = {"add", "subtract", "multiply", "divide"}
DERIVED_NULL_POLICIES = {"zero", "propagate"}
ZERO_NULL_POLICY_ALIASES = {
    "0",
    "fill0",
    "fill_zero",
    "zero",
    "zero_fill",
    "zerofill",
}
PROPAGATE_NULL_POLICY_ALIASES = {
    "as_is",
    "keep",
    "keep_null",
    "nan",
    "none",
    "null",
    "preserve",
    "preserve_null",
    "propagate",
    "propagate_null",
}
AGGREGATE_OPERATOR_ALIASES = {
    "avg": "mean",
    "average": "mean",
    "mean": "mean",
    "sum": "sum",
    "nunique": "nunique",
    "unique": "nunique",
    "distinct": "nunique",
    "distinct_count": "nunique",
    "count_distinct": "nunique",
    "count": "count",
    "min": "min",
    "max": "max",
    "median": "median",
