# 컴포넌트 개요: 02 메타데이터 등록 Context 생성기 rev_2
# 역할: 원문과 활성 MongoDB 메타데이터를 비교해 정제 LLM용 후보와 결정론적 검증 registry를 만듭니다.
# 주요 입력: 저장 요청 payload, 도메인·테이블·메인 필터 snapshot
# 주요 출력: payload, 원문, metadata context, metadata type
# 유지보수 포인트: query/credential/raw registration trace는 LLM context에서 제외하고 저장 writer에는 transient context를 전달하지 않습니다.
# =============================================================================

from __future__ import annotations

import json
import re
import unicodedata
from copy import deepcopy
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, MessageTextInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message

DEFAULT_MAX_CANDIDATES = 16
DEFAULT_MAX_CONTEXT_BYTES = 32768
SECRET_KEY_PARTS = ("password", "passwd", "token", "secret", "api_key", "apikey", "credential", "mongo_uri")
STOP_TOKENS = {
    "등록", "저장", "정보", "내용", "관련", "사용", "데이터", "데이터셋", "테이블", "컬럼", "조건",
    "the", "a", "an", "and", "or", "data", "dataset", "table", "column",
}


def build_authoring_context(
    payload_value: Any,
    domain_items_value: Any = None,
    table_catalog_items_value: Any = None,
    main_flow_filters_value: Any = None,
    max_candidates: Any = str(DEFAULT_MAX_CANDIDATES),
    max_context_bytes: Any = str(DEFAULT_MAX_CONTEXT_BYTES),
) -> dict[str, Any]:
    payload = _payload(payload_value)
    raw_text = str(_dict(payload.get("request")).get("raw_text") or "").strip()
    metadata_type = str(payload.get("metadata_type") or "").strip()
    declared_identity = _declared_identity(raw_text, metadata_type)
    limit = _bounded_int(max_candidates, DEFAULT_MAX_CANDIDATES, 4, 50)
    byte_limit = _bounded_int(max_context_bytes, DEFAULT_MAX_CONTEXT_BYTES, 4096, 65536)

    domain_items, domain_load = _extract_items(domain_items_value, "domain_items")
    table_items, table_load = _extract_items(table_catalog_items_value, "table_catalog_items")
    filter_items, filter_load = _extract_items(main_flow_filters_value, "main_flow_filters")
    registry = _build_registry(domain_items, table_items, filter_items)
    load_summary = {
        "domain_items": _compact_load(domain_load),
        "table_catalog_items": _compact_load(table_load),
        "main_flow_filters": _compact_load(filter_load),
    }
    # Table Catalog authoring has a different namespace boundary from Domain
    # authoring.  The left side of a new ``filter_mappings`` entry is a
    # canonical execution key, while its right side is a physical column owned
    # by the *new* source.  Existing physical column aliases are useful when
    # validating an existing Domain rule, but must not make a new Table
    # Catalog's source column look like a globally ambiguous canonical key.
    canonical_registry = _canonical_registry_for_metadata_type(registry, metadata_type)
    candidates = {
        "datasets": _ranked_candidates(raw_text, registry["datasets"], "dataset_key", limit),
        "canonical_columns": _ranked_candidates(raw_text, canonical_registry, "key", limit),
        "main_filters": _ranked_candidates(raw_text, registry["filters"], "filter_key", limit),
        "domains": (
            _ranked_candidates(raw_text, registry["domains"], "domain_key", limit)
            if _requests_existing_domain_reference(raw_text)
            else []
        ),
    }
    exact_resolutions = _exact_resolutions(raw_text, registry, metadata_type)
    prompt_context = {
        "snapshot_status": load_summary,
        "resolution_policy": "registered_target_with_phrase_local_validation",
        "table_catalog_mapping_policy": (
            "candidate_local_physical_mapping_precedes_global_aliases"
            if metadata_type == "table_catalog"
            else "not_applicable"
        ),
        "declared_identity": declared_identity,
        "datasets": [_prompt_projection(item, "dataset") for item in candidates["datasets"]],
        "canonical_columns": [_prompt_projection(item, "canonical_column") for item in candidates["canonical_columns"]],
        "main_filters": [_prompt_projection(item, "main_filter") for item in candidates["main_filters"]],
        "domains": [_prompt_projection(item, "domain") for item in candidates["domains"]],
        "deterministic_exact_matches": exact_resolutions,
    }
    prompt_context = _fit_context(prompt_context, byte_limit)

    context_status = "ok" if all(item.get("status") == "ok" for item in load_summary.values()) else "error"
    if context_status != "ok":
        diagnostic = {
            "type": "metadata_authoring_context_unavailable",
            "message": "활성 도메인·테이블·메인 필터 metadata snapshot을 모두 읽지 못했습니다.",
            "loads": deepcopy(load_summary),
        }
        # A new Table Catalog can be self-contained: the existing normalizer
        # and writer still verify its source type, query and source-local
        # columns.  A read failure for unrelated active metadata must not
        # preempt that validation.  Explicit references to existing metadata
        # remain unresolved in the later refinement step and still block.
        if metadata_type == "table_catalog":
            diagnostic["message"] += " 새 Table Catalog 후보는 source-local 계약으로 계속 검증합니다."
            diagnostic["severity"] = "warning"
            payload.setdefault("warnings", []).append(diagnostic)
        else:
            diagnostic["message"] += " rev_2 저장을 중단합니다."
            payload.setdefault("errors", []).append(diagnostic)

    context = {
        "status": context_status,
        "load_summary": load_summary,
        "declared_identity": declared_identity,
        "registry": registry,
        "candidates": candidates,
        "exact_resolutions": exact_resolutions,
        "prompt_context": prompt_context,
    }
    payload["metadata_authoring_context"] = context
    payload.setdefault("trace", {})["metadata_contract_snapshot"] = {
        "status": context_status,
        "counts": {
            "domain_items": len(domain_items),
            "table_catalog_items": len(table_items),
            "main_flow_filters": len(filter_items),
        },
        "loads": load_summary,
    }
    return {
        "payload": payload,
        "source_text": raw_text,
        "metadata_type": metadata_type,
        "metadata_context": json.dumps(prompt_context, ensure_ascii=False, separators=(",", ":")),
    }


def _build_registry(domain_items: list[dict[str, Any]], table_items: list[dict[str, Any]], filter_items: list[dict[str, Any]]) -> dict[str, Any]:
    datasets: dict[str, dict[str, Any]] = {}
    filters: dict[str, dict[str, Any]] = {}
    domains: dict[str, dict[str, Any]] = {}
    # ``canonical_sources`` preserves the existing broad registry used by
    # Domain/Main Filter validation.  ``table_catalog_canonical_sources`` is
    # deliberately narrower: it excludes source-local physical columns so a
    # Table Catalog registration cannot be blocked by aliases from unrelated
    # existing datasets.
    canonical_sources: dict[str, dict[str, Any]] = {}
    table_catalog_canonical_sources: dict[str, dict[str, Any]] = {}

    for item in table_items:
        key = str(item.get("dataset_key") or item.get("key") or "").strip()
        if not key:
            continue
        body = _dict(item.get("payload"))
        filter_mappings = _mapping_lists(body.get("filter_mappings"))
        standard_aliases = _mapping_lists(body.get("standard_column_aliases"))
        canonical_columns = _unique_text(
            [
                *filter_mappings,
                *standard_aliases,
                *_string_list(body.get("required_params")),
                *_string_list(body.get("default_detail_columns")),
                *list(_dict(body.get("metric_semantics"))),
            ]
        )
        aliases = _unique_text(
            [
                key,
                body.get("display_name"),
                *_string_list(body.get("aliases")),
            ]
        )
        physical_column_keys = _physical_column_keys(body, filter_mappings)
        column_aliases: dict[str, list[str]] = {}
        for canonical in canonical_columns:
            column_aliases[canonical] = _unique_text(
                [canonical, *filter_mappings.get(canonical, []), *standard_aliases.get(canonical, [])]
            )
            entry = canonical_sources.setdefault(canonical, {"key": canonical, "aliases": [], "datasets": []})
            entry["aliases"] = _unique_text([*entry["aliases"], *column_aliases[canonical]])
            entry["datasets"] = _unique_text([*entry["datasets"], key])

            # A standard alias can be a human/business phrase or a physical
            # source column.  Only the former belongs to the Table Catalog
            # canonical lookup namespace.  Physical values remain visible in
            # the dataset-local ``column_aliases`` contract above.
            semantic_aliases = _unique_text(
                [
                    canonical,
                    *[
                        alias
                        for alias in standard_aliases.get(canonical, [])
                        if _compact(alias) not in physical_column_keys
                    ],
                ]
            )
            table_entry = table_catalog_canonical_sources.setdefault(
                canonical,
                {"key": canonical, "aliases": [], "datasets": []},
            )
            table_entry["aliases"] = _unique_text([*table_entry["aliases"], *semantic_aliases])
            table_entry["datasets"] = _unique_text([*table_entry["datasets"], key])
        datasets[key] = {
            "dataset_key": key,
            "display_name": str(body.get("display_name") or key),
            "aliases": aliases,
            "canonical_columns": canonical_columns,
            "column_aliases": column_aliases,
            "filter_mappings": filter_mappings,
            "standard_column_aliases": standard_aliases,
        }

    for item in filter_items:
        key = str(item.get("filter_key") or item.get("key") or "").strip()
        if not key:
            continue
        body = _dict(item.get("payload"))
        semantic_aliases = _unique_text([key, body.get("display_name"), *_string_list(body.get("aliases"))])
        aliases = _unique_text([*semantic_aliases, *_string_list(body.get("column_candidates"))])
        filters[key] = {
            "filter_key": key,
            "display_name": str(body.get("display_name") or key),
            "aliases": aliases,
            "column_candidates": _string_list(body.get("column_candidates")),
        }
        # Preserve the existing broad registry for Domain/Main Filter paths.
        # The Table Catalog path below deliberately receives only
        # ``semantic_aliases`` so a physical candidate cannot be mistaken for
        # a globally unique source-local mapping during new-table authoring.
        entry = canonical_sources.setdefault(key, {"key": key, "aliases": [], "datasets": []})
        entry["aliases"] = _unique_text([*entry["aliases"], *aliases])
        table_entry = table_catalog_canonical_sources.setdefault(key, {"key": key, "aliases": [], "datasets": []})
        table_entry["aliases"] = _unique_text([*table_entry["aliases"], *semantic_aliases])

    for item in domain_items:
        section = str(item.get("section") or "").strip()
        key = str(item.get("key") or "").strip()
        if not section or not key:
            continue
        body = _dict(item.get("payload"))
        domain_key = f"{section}:{key}"
        domains[domain_key] = {
            "domain_key": domain_key,
            "section": section,
            "key": key,
            "display_name": str(body.get("display_name") or key),
            "aliases": _unique_text([key, body.get("display_name"), *_string_list(body.get("aliases"))]),
        }

    return {
        "datasets": datasets,
        "canonical_columns": canonical_sources,
        "table_catalog_canonical_columns": table_catalog_canonical_sources,
        "filters": filters,
        "domains": domains,
    }


def _ranked_candidates(raw_text: str, entries: dict[str, dict[str, Any]], key_field: str, limit: int) -> list[dict[str, Any]]:
    ranked = []
    for entry in entries.values():
        score = _score(raw_text, _string_list(entry.get("aliases")))
        if score > 0:
            candidate = deepcopy(entry)
            candidate["match_score"] = score
            ranked.append(candidate)
    ranked.sort(key=lambda item: (-int(item.get("match_score") or 0), str(item.get(key_field) or "")))
    return ranked[:limit]


def _score(raw_text: str, aliases: list[str]) -> int:
    raw_compact = _compact(raw_text)
    raw_tokens = set(_tokens(raw_text))
    best = 0
    for alias in aliases:
        alias_compact = _compact(alias)
        if not alias_compact:
            continue
        score = 0
        if len(alias_compact) >= 2 and alias_compact in raw_compact:
            score += 100 + min(len(alias_compact), 30)
        alias_tokens = set(_tokens(alias))
        overlap = raw_tokens & alias_tokens
        score += len(overlap) * 12
        if alias_tokens and alias_tokens <= raw_tokens:
            score += 20
        best = max(best, score)
    return best


def _canonical_registry_for_metadata_type(registry: dict[str, Any], metadata_type: str) -> dict[str, dict[str, Any]]:
    if metadata_type == "table_catalog":
        scoped = _dict(registry.get("table_catalog_canonical_columns"))
        if scoped:
            return scoped
    return _dict(registry.get("canonical_columns"))


def _exact_resolutions(raw_text: str, registry: dict[str, Any], metadata_type: str = "") -> list[dict[str, str]]:
    raw_compact = _compact(raw_text)
    results: list[dict[str, str]] = []
    specs = (
        ("dataset", registry["datasets"], "dataset_key"),
        ("canonical_column", _canonical_registry_for_metadata_type(registry, metadata_type), "key"),
        ("main_filter", registry["filters"], "filter_key"),
    )
    for kind, entries, target_field in specs:
        alias_targets: dict[str, set[str]] = {}
        alias_original: dict[str, str] = {}
        for entry in entries.values():
            target = str(entry.get(target_field) or "").strip()
            for alias in _string_list(entry.get("aliases")):
                compact = _compact(alias)
                if len(compact) < 2:
                    continue
                alias_targets.setdefault(compact, set()).add(target)
                alias_original.setdefault(compact, alias)
        for alias, targets in alias_targets.items():
            target = next(iter(targets)) if len(targets) == 1 else ""
            if alias in raw_compact and target and alias != _compact(target):
                results.append({"kind": kind, "input": alias_original[alias], "target": target, "evidence": "registered_unique_alias"})
    return _dedupe_references(results)


def _declared_identity(raw_text: str, metadata_type: str) -> dict[str, str]:
    """Extract only identifiers that the user explicitly wrote.

    These values are authoritative for rev_2.  They are kept outside the item
    document and later used by the contract guard so an LLM cannot rename a
    requested identity to avoid an existing-key match.
    """

    patterns = {
        "section": r"(?i)(?<![A-Za-z0-9_])section\s*(?:은|는|:|=)?\s*[`'\"]?([A-Za-z][A-Za-z0-9_]*)",
        "key": r"(?i)(?<![A-Za-z0-9_])key\s*(?:은|는|:|=)?\s*[`'\"]?([A-Za-z][A-Za-z0-9_]*)",
        "dataset_key": r"(?i)(?<![A-Za-z0-9_])dataset_key\s*(?:은|는|:|=)?\s*[`'\"]?([A-Za-z][A-Za-z0-9_]*)",
        "filter_key": r"(?i)(?<![A-Za-z0-9_])filter_key\s*(?:은|는|:|=)?\s*[`'\"]?([A-Za-z][A-Za-z0-9_]*)",
        "status": r"(?i)(?<![A-Za-z0-9_])status\s*(?:은|는|:|=)?\s*[`'\"]?([A-Za-z][A-Za-z0-9_]*)",
    }
    allowed = {
        "domain": ("section", "key", "status"),
        "table_catalog": ("dataset_key", "status"),
        "main_flow_filter": ("filter_key", "status"),
    }.get(metadata_type, ())
    result: dict[str, str] = {}
    for field in allowed:
        match = re.search(patterns[field], raw_text)
        if match:
            result[field] = match.group(1)
    return result


def _requests_existing_domain_reference(raw_text: str) -> bool:
    lowered = str(raw_text or "").casefold()
    return any(
        cue in lowered
        for cue in (
            "기존 도메인",
            "도메인 참조",
            "도메인 규칙을 참조",
            "domain reference",
            "reuse domain",
        )
    )


def _prompt_projection(item: dict[str, Any], kind: str) -> dict[str, Any]:
    allowed = {
        "dataset": ("dataset_key", "display_name", "aliases", "canonical_columns", "filter_mappings", "standard_column_aliases", "match_score"),
        "canonical_column": ("key", "aliases", "datasets", "match_score"),
        "main_filter": ("filter_key", "display_name", "aliases", "column_candidates", "match_score"),
        "domain": ("domain_key", "section", "key", "display_name", "aliases", "match_score"),
    }[kind]
    return {key: deepcopy(item[key]) for key in allowed if key in item}


def _fit_context(context: dict[str, Any], byte_limit: int) -> dict[str, Any]:
    result = deepcopy(context)
    while len(json.dumps(result, ensure_ascii=False).encode("utf-8")) > byte_limit:
        lists = [result.get(name) for name in ("domains", "main_filters", "canonical_columns", "datasets")]
        target = max((value for value in lists if isinstance(value, list) and value), key=len, default=None)
        if target is None:
            break
        target.pop()
    return result


def _extract_items(value: Any, key: str) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    data = getattr(value, "data", value)
    if not isinstance(data, dict):
        return [], {"status": "missing", "count": 0, "errors": [{"type": "missing_snapshot_input", "message": f"{key} snapshot 입력이 없습니다."}]}
    items = [deepcopy(item) for item in data.get(key, []) if isinstance(item, dict)] if isinstance(data.get(key), list) else []
    load = deepcopy(data.get("metadata_load")) if isinstance(data.get("metadata_load"), dict) else {}
    load.setdefault("status", "ok" if key in data else "missing")
    load.setdefault("count", len(items))
    load.setdefault("errors", [])
    return items, load


def _compact_load(value: dict[str, Any]) -> dict[str, Any]:
    return {key: deepcopy(value.get(key)) for key in ("status", "count", "database", "collection_name", "truncated", "errors") if key in value}


def _mapping_lists(value: Any) -> dict[str, list[str]]:
    if not isinstance(value, dict):
        return {}
    result: dict[str, list[str]] = {}
    for key, raw in value.items():
        canonical = str(key or "").strip()
        if canonical:
            result[canonical] = _unique_text(_string_list(raw) if isinstance(raw, list) else [raw])
    return result


def _physical_column_keys(body: dict[str, Any], filter_mappings: dict[str, list[str]]) -> set[str]:
    """Return source-local physical column names declared by one catalog item.

    Table Catalog's filter mappings and query result columns are source schema,
    not cross-dataset canonical aliases.  Keeping this small helper here makes
    the boundary explicit without changing the existing dataset-local contract.
    """

    names: list[str] = [
        value
        for aliases in filter_mappings.values()
        for value in aliases
    ]
    for field in ("required_param_mappings",):
        names.extend(
            value
            for aliases in _mapping_lists(body.get(field)).values()
            for value in aliases
        )
    columns = body.get("columns")
    values = columns if isinstance(columns, list) else list(columns) if isinstance(columns, dict) else []
    for value in values:
        if isinstance(value, dict):
            value = value.get("column_name") or value.get("name") or value.get("column") or value.get("field")
        text = str(value or "").strip()
        if text:
            names.append(text)
    return {_compact(value) for value in names if _compact(value)}


def _selection_text(value: Any) -> list[str]:
    if isinstance(value, list):
        return _string_list(value)
    if not isinstance(value, dict):
        return []
    return _unique_text([*_string_list(value.get("use_when")), *_string_list(value.get("rules"))])


def _tokens(value: Any) -> list[str]:
    separated = re.sub(
        r"(?<=[A-Za-z0-9_])(?=[가-힣])|(?<=[가-힣])(?=[A-Za-z0-9_])",
        " ",
        str(value or ""),
    )
    return [
        token
        for token in (_normalize_text(item) for item in re.findall(r"[가-힣A-Za-z0-9_]+", separated))
        if len(token) >= 2 and token not in STOP_TOKENS
    ]


def _compact(value: Any) -> str:
    return re.sub(r"[^0-9a-z가-힣]+", "", _normalize_text(value))


def _normalize_text(value: Any) -> str:
    return unicodedata.normalize("NFKC", str(value or "")).casefold().strip()


def _dedupe_references(values: list[dict[str, str]]) -> list[dict[str, str]]:
    result = []
    seen = set()
    for item in values:
        marker = (item.get("kind"), _compact(item.get("input")), item.get("target"))
        if marker not in seen:
            seen.add(marker)
            result.append(item)
    return result


def _unique_text(values: Any) -> list[str]:
    result = []
    seen = set()
    for value in values if isinstance(values, (list, tuple, set)) else []:
        text = str(value or "").strip()
        if text and text not in seen and not _is_secret_key(text):
            seen.add(text)
            result.append(text)
    return result


def _string_list(value: Any) -> list[str]:
    return [str(item).strip() for item in value if str(item or "").strip()] if isinstance(value, list) else []


def _is_secret_key(value: str) -> bool:
    normalized = re.sub(r"[^a-z0-9]+", "_", str(value or "").casefold())
    return any(part in normalized for part in SECRET_KEY_PARTS)


def _bounded_int(value: Any, default: int, minimum: int, maximum: int) -> int:
    try:
        return min(maximum, max(minimum, int(value)))
    except Exception:
        return default


def _payload(value: Any) -> dict[str, Any]:
    data = getattr(value, "data", value)
    return deepcopy(data) if isinstance(data, dict) else {}


def _dict(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


class MetadataAuthoringContextBuilderRev2(Component):
    display_name = "02 메타데이터 등록 Context 생성기 rev_2"
    description = "활성 metadata snapshot에서 원문과 관련된 계약 후보와 검증 registry를 만듭니다."
    inputs = [
        DataInput(name="payload", display_name="저장 요청 페이로드", required=True),
        DataInput(name="domain_items", display_name="도메인 메타데이터", required=True),
        DataInput(name="table_catalog_items", display_name="테이블 카탈로그", required=True),
        DataInput(name="main_flow_filters", display_name="메인 필터", required=True),
        MessageTextInput(name="max_candidates", display_name="종류별 최대 후보 수", value=str(DEFAULT_MAX_CANDIDATES), advanced=True),
        MessageTextInput(name="max_context_bytes", display_name="최대 LLM Context 바이트", value=str(DEFAULT_MAX_CONTEXT_BYTES), advanced=True),
    ]
    outputs = [
        Output(name="payload_out", display_name="페이로드 출력", method="build_payload", types=["Data"], group_outputs=True),
        Output(name="source_text", display_name="사용자 원문", method="build_source_text", types=["Message"], group_outputs=True),
        Output(name="metadata_context", display_name="등록 계약 후보", method="build_metadata_context", types=["Message"], group_outputs=True),
        Output(name="metadata_type", display_name="메타데이터 종류", method="build_metadata_type", types=["Message"], group_outputs=True),
    ]

    def _build_once(self) -> dict[str, Any]:
        cached = getattr(self, "_authoring_context_result", None)
        if isinstance(cached, dict):
            return cached
        result = build_authoring_context(
            getattr(self, "payload", None),
            getattr(self, "domain_items", None),
            getattr(self, "table_catalog_items", None),
            getattr(self, "main_flow_filters", None),
            getattr(self, "max_candidates", str(DEFAULT_MAX_CANDIDATES)),
            getattr(self, "max_context_bytes", str(DEFAULT_MAX_CONTEXT_BYTES)),
        )
        self._authoring_context_result = result
        return result

    def build_payload(self) -> Data:
        return Data(data=deepcopy(self._build_once()["payload"]))

    def build_source_text(self) -> Message:
        return Message(text=self._build_once()["source_text"])

    def build_metadata_context(self) -> Message:
        return Message(text=self._build_once()["metadata_context"])

    def build_metadata_type(self) -> Message:
        return Message(text=self._build_once()["metadata_type"])

# -*- coding: utf-8 -*-
# =============================================================================
# 컴포넌트 개요: 04 메타데이터 등록 정제 결과 검증기 rev_2
# 역할: 정제 LLM 응답을 파싱하고 실제 snapshot 후보에 존재하는 유일한 참조만 승인합니다.
# 주요 입력: Context payload, 정제 LLM 응답
# 주요 출력: 정제안과 검증 근거가 포함된 payload
# 유지보수 포인트: LLM이 제안한 key가 실제 registry/candidate에 없으면 저장 단계로 신뢰 전달하지 않습니다.
# =============================================================================

from __future__ import annotations

import json
import re
import textwrap
import unicodedata
from copy import deepcopy
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, MessageTextInput, Output
from lfx.schema.data import Data

KIND_ALIASES = {
    "dataset": "dataset",
    "dataset_key": "dataset",
    "table": "dataset",
    "canonical_column": "canonical_column",
    "column": "canonical_column",
    "standard_column": "canonical_column",
    "main_filter": "main_filter",
    "filter": "main_filter",
    "filter_key": "main_filter",
    "domain": "domain",
    "domain_item": "domain",
}


def normalize_refinement(payload_value: Any, llm_response: Any) -> dict[str, Any]:
    payload = _payload(payload_value)
    parsed = _json_object(llm_response)
    context = _dict(payload.get("metadata_authoring_context"))
    registry = _dict(context.get("registry"))
    raw_text = str(_dict(payload.get("request")).get("raw_text") or "").strip()
    metadata_type = str(payload.get("metadata_type") or "").strip()
    errors: list[dict[str, Any]] = []
    advisory_references: list[dict[str, Any]] = []

    if not parsed:
        errors.append(
            {
                "type": "metadata_refinement_parse_error",
                "message": "메타데이터 정제 응답을 JSON object로 해석하지 못했습니다.",
            }
        )

    resolved: list[dict[str, Any]] = []
    for raw in _list(parsed.get("resolved_references")):
        advisory = _table_catalog_optional_reference_advisory(
            raw,
            metadata_type,
            raw_text,
            from_unresolved=False,
        )
        if advisory:
            advisory_references.append(advisory)
            continue
        checked, error = _validate_reference(raw, context, registry, metadata_type=metadata_type)
        if checked and _keep_reference(checked, context, raw_text):
            resolved.append(checked)
        if error:
            errors.append(error)
    resolved = _dedupe_references(resolved)

    unresolved = []
    for raw in _normalize_unresolved(parsed.get("unresolved_references")):
        advisory = _table_catalog_optional_reference_advisory(
            raw,
            metadata_type,
            raw_text,
            from_unresolved=True,
        )
        if advisory:
            advisory_references.append(advisory)
            continue
        unresolved.append(raw)
    for error in errors:
        if str(error.get("type") or "") not in {
            "unknown_metadata_reference",
            "reference_not_in_context",
            "ambiguous_metadata_reference",
            "metadata_reference_mismatch",
        }:
            continue
        source = str(error.get("input") or "").strip()
        if source:
            unresolved.append(
                {
                    "kind": str(error.get("kind") or "unknown"),
                    "input": source,
                    "candidates": _unique_text(_string_list(error.get("candidates")) + [error.get("registered_target")]),
                    "suggested_target": str(error.get("target") or error.get("registered_target") or "").strip(),
                    "reason": str(error.get("message") or "등록 계약을 하나로 확정하지 못했습니다."),
                }
            )
    conflicts = _reference_conflicts(resolved)
    for conflict in conflicts:
        errors.append(
            {
                "type": "ambiguous_metadata_reference",
                "message": f"'{conflict['input']}' 표현이 여러 계약으로 해석되어 자동 확정하지 않았습니다: {', '.join(conflict['targets'])}",
                "input": conflict["input"],
                "candidates": conflict["targets"],
            }
        )
        unresolved.append(
            {
                "kind": conflict["kind"],
                "input": conflict["input"],
                "candidates": conflict["targets"],
                "reason": "동일 표현에 둘 이상의 등록 계약이 연결되었습니다.",
            }
        )
    if conflicts:
        conflicted = {(item["kind"], _compact(item["input"])) for item in conflicts}
        resolved = [item for item in resolved if (item["kind"], _compact(item["input"])) not in conflicted]

    unresolved = _drop_resolved_unresolved(unresolved, resolved)
    parsed_missing = _drop_table_catalog_optional_missing_information(
        _string_list(parsed.get("missing_information")),
        metadata_type,
        advisory_references,
    )
    parsed_missing = _drop_resolved_missing(parsed_missing, resolved)
    missing = _unique_text(
        [
            *parsed_missing,
            *[f"'{item.get('input', '')}'의 실제 계약을 하나로 지정해 주세요." for item in unresolved if str(item.get("input") or "").strip()],
            *[str(error.get("message") or "") for error in errors if error.get("type") in {"unknown_metadata_reference", "reference_not_in_context"}],
        ]
    )
    assumptions = _unique_text(_string_list(parsed.get("assumptions")))
    refined_text = str(parsed.get("refined_text") or raw_text).strip()
    unsafe_refined_text = _contains_unapproved_target(refined_text, unresolved, errors)
    if unsafe_refined_text:
        refined_text = raw_text
    refined_text = _lock_declared_identity(refined_text, _dict(context.get("declared_identity")))
    formatted_refined_text = refined_text if unsafe_refined_text else _format_refined_text(refined_text)
    formatting_applied = formatted_refined_text != refined_text
    refined_text = formatted_refined_text
    # A Table Catalog model occasionally marks ``needs_more_input`` solely
    # because it treated a source-local column mapping as an unregistered
    # main_filter/canonical reference.  Once every such reference has been
    # converted to an advisory and no concrete missing detail remains, do not
    # suppress the candidate.  The downstream writer still validates source
    # type, query, declared columns and duplicate physical mappings.
    reported_needs_input = _truthy(parsed.get("needs_more_input"))
    advisory_only_needs_input = (
        metadata_type == "table_catalog"
        and bool(advisory_references)
        and not missing
        and not unresolved
    )
    needs_more_input = (reported_needs_input and not advisory_only_needs_input) or bool(missing) or bool(unresolved)

    current_refinement = _dict(payload.get("refinement"))
    current_refinement.update(
        {
            "refined_text": refined_text,
            "needs_more_input": needs_more_input,
            "missing_information": missing,
            "assumptions": assumptions,
        }
    )
    payload["refinement"] = current_refinement
    payload["metadata_authoring_draft"] = {
        "original_text": raw_text,
        "refined_text": refined_text,
        "resolved_references": resolved,
        "unresolved_references": unresolved,
        "missing_information": missing,
        "assumptions": assumptions,
        "needs_more_input": needs_more_input,
    }
    payload.setdefault("errors", []).extend(errors)
    if advisory_references:
        payload.setdefault("warnings", []).extend(advisory_references)
    payload.setdefault("trace", {})["contract_resolution"] = {
        "status": "needs_input" if needs_more_input else "resolved",
        "resolved_count": len(resolved),
        "unresolved_count": len(unresolved),
        "resolved_references": deepcopy(resolved),
        "unresolved_references": deepcopy(unresolved),
        "refined_text_source": "original_text_fallback" if unsafe_refined_text else "llm_refined_text",
        "refined_text_formatting": {
            "applied": formatting_applied,
            "style": "readable_multiline_v1",
        },
        "table_catalog_reference_scope": {
            "status": "advisory_local_mapping" if advisory_references else "not_needed",
            "advisory_count": len(advisory_references),
            "advisories": deepcopy(advisory_references),
        },
    }
    return payload


def _validate_reference(
    value: Any,
    context: dict[str, Any],
    registry: dict[str, Any],
    metadata_type: str = "",
    deterministic: bool = False,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    if not isinstance(value, dict):
        return None, {"type": "invalid_metadata_reference", "message": "resolved_references 항목은 object여야 합니다."}
    kind = KIND_ALIASES.get(str(value.get("kind") or "").strip().lower(), "")
    source = str(value.get("input") or "").strip()
    target = str(value.get("target") or "").strip()
    if not kind or not source or not target:
        return None, {"type": "invalid_metadata_reference", "message": "확정 참조에는 kind, input, target이 모두 필요합니다."}
    entries, target_field = _registry_spec(registry, kind, metadata_type)
    actual_target = _case_insensitive_key(entries, target)
    if not actual_target:
        return None, {
            "type": "unknown_metadata_reference",
            "message": f"'{source}'을(를) 연결한 '{target}'은 현재 활성 {kind} registry에 없습니다.",
            "kind": kind,
            "input": source,
            "target": target,
        }
    entry = _dict(entries.get(actual_target))
    canonical_target = str(entry.get(target_field) or actual_target).strip()
    allowed = _candidate_targets(context, kind, target_field)
    source_targets = _exact_alias_targets(entries, target_field, source)
    if len(source_targets) > 1:
        return None, {
            "type": "ambiguous_metadata_reference",
            "message": f"'{source}' 표현이 여러 활성 {kind} 계약과 정확히 일치합니다: {', '.join(source_targets)}",
            "kind": kind,
            "input": source,
            "target": canonical_target,
            "candidates": source_targets,
        }
    if len(source_targets) == 1 and source_targets[0].casefold() != canonical_target.casefold():
        return None, {
            "type": "metadata_reference_mismatch",
            "message": f"'{source}'의 등록 계약은 '{source_targets[0]}'이지만 LLM이 '{canonical_target}'을 제안했습니다.",
            "kind": kind,
            "input": source,
            "target": canonical_target,
            "registered_target": source_targets[0],
        }
    phrase_targets = _phrase_alias_targets(entries, target_field, source) if not source_targets else []
    if len(phrase_targets) > 1:
        return None, {
            "type": "ambiguous_metadata_reference",
            "message": f"'{source}' 표현이 여러 활성 {kind} 계약과 같은 수준으로 일치합니다: {', '.join(phrase_targets)}",
            "kind": kind,
            "input": source,
            "target": canonical_target,
            "candidates": phrase_targets,
        }
    if len(phrase_targets) == 1 and phrase_targets[0].casefold() != canonical_target.casefold():
        return None, {
            "type": "metadata_reference_mismatch",
            "message": f"'{source}' 문구는 '{phrase_targets[0]}'에 가장 가깝지만 LLM이 '{canonical_target}'을 제안했습니다.",
            "kind": kind,
            "input": source,
            "target": canonical_target,
            "registered_target": phrase_targets[0],
        }
    allowed_folded = {item.casefold() for item in allowed}
    has_phrase_evidence = bool(source_targets or phrase_targets)
    if not deterministic and not has_phrase_evidence and canonical_target.casefold() not in allowed_folded:
        return None, {
            "type": "reference_not_in_context",
            "message": f"'{source}' → '{canonical_target}' 연결은 이번 원문과 매칭된 등록 후보에 없어 자동 확정하지 않았습니다.",
            "kind": kind,
            "input": source,
            "target": canonical_target,
            "candidates": allowed,
        }
    return (
        {
            "kind": kind,
            "input": source,
            "target": canonical_target,
            "evidence": str(value.get("evidence") or ("registered_unique_alias" if deterministic else "registered_candidate")).strip(),
        },
        None,
    )


def _registry_spec(registry: dict[str, Any], kind: str, metadata_type: str = "") -> tuple[dict[str, Any], str]:
    if kind == "dataset":
        return _dict(registry.get("datasets")), "dataset_key"
    if kind == "canonical_column":
        if metadata_type == "table_catalog":
            scoped = _dict(registry.get("table_catalog_canonical_columns"))
            if scoped:
                return scoped, "key"
        return _dict(registry.get("canonical_columns")), "key"
    if kind == "main_filter":
        return _dict(registry.get("filters")), "filter_key"
    return _dict(registry.get("domains")), "domain_key"


def _candidate_targets(context: dict[str, Any], kind: str, target_field: str) -> list[str]:
    key = {"dataset": "datasets", "canonical_column": "canonical_columns", "main_filter": "main_filters", "domain": "domains"}[kind]
    return _unique_text([_dict(item).get(target_field) for item in _list(_dict(context.get("candidates")).get(key))])


def _case_insensitive_key(entries: dict[str, Any], target: str) -> str:
    folded = target.casefold()
    return next((key for key in entries if str(key).casefold() == folded), "")


def _exact_alias_targets(entries: dict[str, Any], target_field: str, source: str) -> list[str]:
    compact = _compact(source)
    targets = []
    for key, raw_entry in entries.items():
        entry = _dict(raw_entry)
        target = str(entry.get(target_field) or key).strip()
        aliases = _unique_text([target, *_string_list(entry.get("aliases"))])
        if compact and any(_compact(alias) == compact for alias in aliases):
            targets.append(target)
    return _unique_text(targets)


def _phrase_alias_targets(entries: dict[str, Any], target_field: str, source: str) -> list[str]:
    scored: list[tuple[int, str]] = []
    for key, raw_entry in entries.items():
        entry = _dict(raw_entry)
        target = str(entry.get(target_field) or key).strip()
        aliases = _unique_text([target, *_string_list(entry.get("aliases"))])
        score = max((_phrase_score(source, alias) for alias in aliases), default=0)
        if score > 0:
            scored.append((score, target))
    if not scored:
        return []
    best = max(score for score, _ in scored)
    return _unique_text([target for score, target in scored if score == best])


def _phrase_score(source: str, alias: str) -> int:
    source_compact = _compact(source)
    alias_compact = _compact(alias)
    if min(len(source_compact), len(alias_compact)) >= 4 and (
        source_compact in alias_compact or alias_compact in source_compact
    ):
        return 100 + min(len(source_compact), len(alias_compact))
    source_tokens = set(_tokens(source))
    alias_tokens = set(_tokens(alias))
    overlap = source_tokens & alias_tokens
    return len(overlap) * 10 if len(overlap) >= 2 else 0


def _normalize_unresolved(value: Any) -> list[dict[str, Any]]:
    result = []
    for item in _list(value):
        if not isinstance(item, dict):
            continue
        source = str(item.get("input") or "").strip()
        if not source:
            continue
        result.append(
            {
                "kind": KIND_ALIASES.get(str(item.get("kind") or "").strip().lower(), str(item.get("kind") or "unknown")),
                "input": source,
                "candidates": _unique_text(_string_list(item.get("candidates"))),
                "suggested_target": str(item.get("suggested_target") or item.get("target") or "").strip(),
                "reason": str(item.get("reason") or "등록 계약을 하나로 확정하지 못했습니다.").strip(),
            }
        )
    return result


def _table_catalog_optional_reference_advisory(
    value: Any,
    metadata_type: str,
    raw_text: str,
    *,
    from_unresolved: bool,
) -> dict[str, Any] | None:
    """Downgrade source-local mapping noise only for Table Catalog authoring.

    ``filter_mappings`` establishes a new table's own canonical-to-physical
    binding.  It is not a request to register or resolve a reusable
    ``main_filter``.  Likewise, a physical identifier such as ``WORK_DT`` is
    not a global canonical reference merely because an older dataset happened
    to use it under multiple keys.  Domain and Main Flow Filter authoring keep
    the existing strict reference behavior.
    """

    if metadata_type != "table_catalog" or not isinstance(value, dict):
        return None
    kind = KIND_ALIASES.get(str(value.get("kind") or "").strip().lower(), "")
    source = str(value.get("input") or "").strip()
    target = str(value.get("target") or value.get("suggested_target") or "").strip()
    if not kind or not source:
        return None
    if kind == "main_filter" and not _requests_explicit_main_filter_reference(raw_text):
        return {
            "type": "table_catalog_optional_main_filter_reference",
            "message": (
                f"'{source}' → '{target or '미지정'}'은(는) 신규 Table Catalog의 컬럼 매핑으로 처리했습니다. "
                "기존 main_filter 등록 여부는 저장을 막지 않습니다."
            ),
            "kind": kind,
            "input": source,
            "target": target,
            "scope": "candidate_local_filter_mapping",
        }
    if (
        from_unresolved
        and kind == "canonical_column"
        and _looks_like_source_identifier(source)
        and _has_table_mapping_context(raw_text)
        and not _requests_explicit_global_canonical_reference(raw_text)
    ):
        return {
            "type": "table_catalog_source_column_reference",
            "message": (
                f"'{source}'은(는) 신규 Table Catalog의 source column 후보로 처리했습니다. "
                "기존 데이터셋의 canonical alias 충돌은 저장을 막지 않습니다."
            ),
            "kind": kind,
            "input": source,
            "target": target,
            "scope": "candidate_local_source_schema",
        }
    return None


def _requests_explicit_main_filter_reference(raw_text: str) -> bool:
    lowered = str(raw_text or "").casefold()
    return any(
        cue in lowered
        for cue in (
            "기존 main filter",
            "기존 main_flow_filter",
            "등록된 main filter",
            "등록된 main_flow_filter",
            "기존 메인 필터",
            "등록된 메인 필터",
            "활성 메인 필터",
            "main_filter를 참조",
            "main filter를 참조",
        )
    )


def _requests_explicit_global_canonical_reference(raw_text: str) -> bool:
    lowered = str(raw_text or "").casefold()
    return any(
        cue in lowered
        for cue in (
            "기존 표준 컬럼",
            "등록된 표준 컬럼",
            "활성 표준 컬럼",
            "canonical_column을 참조",
            "canonical column을 참조",
        )
    )


def _has_table_mapping_context(raw_text: str) -> bool:
    lowered = str(raw_text or "").casefold()
    return any(
        cue in lowered
        for cue in (
            "filter_mappings",
            "filter mapping",
            "컬럼 매핑",
            "매핑",
            "대응",
            "실제 컬럼",
            "source column",
            "query_template",
            "조회 sql",
            "select ",
        )
    )


def _looks_like_source_identifier(value: str) -> bool:
    return bool(re.fullmatch(r"[A-Za-z][A-Za-z0-9_]*", str(value or "").strip()))


def _drop_table_catalog_optional_missing_information(
    values: list[str],
    metadata_type: str,
    advisories: list[dict[str, Any]],
) -> list[str]:
    if metadata_type != "table_catalog" or not advisories:
        return values
    advisory_inputs = [_compact(item.get("input")) for item in advisories if _compact(item.get("input"))]
    result = []
    for value in values:
        compact = _compact(value)
        refers_to_advisory = any(source and source in compact for source in advisory_inputs)
        registry_only_reason = any(
            token in str(value or "").casefold()
            for token in (
                "main_filter",
                "main filter",
                "메인 필터",
                "canonical",
                "canonical alias",
                "활성 계약",
                "등록 계약",
            )
        )
        if refers_to_advisory and registry_only_reason:
            continue
        result.append(value)
    return result


def _reference_conflicts(resolved: list[dict[str, Any]]) -> list[dict[str, Any]]:
    grouped: dict[tuple[str, str], dict[str, Any]] = {}
    for item in resolved:
        marker = (str(item.get("kind") or ""), _compact(item.get("input")))
        group = grouped.setdefault(marker, {"kind": marker[0], "input": str(item.get("input") or ""), "targets": []})
        group["targets"] = _unique_text([*group["targets"], item.get("target")])
    return [item for item in grouped.values() if len(item["targets"]) > 1]


def _append_reference_block(text: str, resolved: list[dict[str, Any]], unresolved: list[dict[str, Any]]) -> str:
    sections = [text.strip()] if text.strip() else []
    if resolved:
        lines = ["[확정된 기존 메타데이터 참조]"]
        lines.extend(f"- {item['kind']}: {item['input']} -> {item['target']}" for item in resolved)
        sections.append("\n".join(lines))
    if unresolved:
        lines = ["[저장 전 확인이 필요한 참조]"]
        for item in unresolved:
            candidates = ", ".join(_string_list(item.get("candidates"))) or "등록 후보 없음"
            lines.append(f"- {item['input']}: {candidates} ({item.get('reason', '')})")
        sections.append("\n".join(lines))
    return "\n\n".join(sections)


def _keep_reference(reference: dict[str, Any], context: dict[str, Any], raw_text: str) -> bool:
    source = str(reference.get("input") or "").strip()
    target = str(reference.get("target") or "").strip()
    if _compact(source) == _compact(target):
        return False
    if str(reference.get("kind") or "") != "domain":
        return True
    declared = _dict(context.get("declared_identity"))
    declared_target = f"{declared.get('section', '')}:{declared.get('key', '')}".strip(":")
    if declared_target and target.casefold() == declared_target.casefold():
        return False
    lowered = raw_text.casefold()
    return any(token in lowered for token in ("기존", "참조", "재사용", "reuse", "reference"))


def _drop_resolved_unresolved(
    unresolved: list[dict[str, Any]], resolved: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    resolved_markers = {
        (str(item.get("kind") or ""), _compact(item.get("input")))
        for item in resolved
    }
    return [
        item
        for item in unresolved
        if (str(item.get("kind") or ""), _compact(item.get("input"))) not in resolved_markers
    ]


def _drop_resolved_missing(values: list[str], resolved: list[dict[str, Any]]) -> list[str]:
    resolved_inputs = [_compact(item.get("input")) for item in resolved if str(item.get("input") or "").strip()]
    result = []
    for value in values:
        compact = _compact(value)
        is_resolution_request = any(token in value for token in ("실제 계약", "하나로 지정", "하나를 선택", "확정"))
        if is_resolution_request and any(source and source in compact for source in resolved_inputs):
            continue
        result.append(value)
    return result


def _lock_declared_identity(text: str, declared: dict[str, Any]) -> str:
    result = str(text or "").strip()
    missing: dict[str, str] = {}
    for field in ("dataset_key", "filter_key", "section", "key", "status"):
        expected = str(declared.get(field) or "").strip()
        if not expected:
            continue
        pattern = re.compile(
            rf"(?i)(?<![A-Za-z0-9_])({re.escape(field)}\s*(?:은|는|:|=)\s*[`'\"]?)[A-Za-z][A-Za-z0-9_]*"
        )
        if pattern.search(result):
            result = pattern.sub(lambda match: match.group(1) + expected, result)
        else:
            missing[field] = expected
    if missing:
        labels = {
            "dataset_key": "dataset_key는",
            "filter_key": "filter_key는",
            "section": "section은",
            "key": "key는",
            "status": "status는",
        }
        order = ("dataset_key", "filter_key", "section", "key", "status")
        identity = ", ".join(f"{labels[field]} {missing[field]}" for field in order if field in missing)
        result = "\n\n".join(part for part in (result, f"{identity}로 등록해.") if part)
    return result


_INLINE_QUOTED_SQL = re.compile(
    r"(?is)(?P<label>(?:조회\s*)?(?:SQL|쿼리)(?:문)?(?:은|는))\s*"
    r"(?P<quote>['\"])(?P<sql>(?:SELECT|WITH)\b.*?)(?P=quote)\s*"
    r"(?P<ending>이다|입니다|야|이야|예요)?(?P<period>\.)"
)
_INLINE_UNQUOTED_SQL = re.compile(
    r"(?is)(?P<label>(?:조회\s*)?(?:SQL|쿼리)(?:문)?(?:은|는))\s*"
    r"(?P<sql>(?:SELECT|WITH)\b.*?)(?P<ending>이다|입니다|야|이야|예요)(?P<period>\.)"
)
_FENCED_SQL = re.compile(r"(?is)```(?:sql)?\s*(?P<sql>(?:SELECT|WITH)\b.*?)\s*```")
_SQL_PROTECTED_SEGMENT = re.compile(
    r"(?ms)--[^\r\n]*(?:\n|$)|/\*.*?\*/|'(?:''|[^'])*'|\"(?:\"\"|[^\"])*\""
)
_SENTENCE_BOUNDARY = re.compile(r"(?<=[.!?])\s+(?=[`'\"(\[A-Za-z0-9가-힣])")
_IDENTITY_SENTENCE = re.compile(
    r"(?i)(?:dataset_key|filter_key|section|(?:^|\s)key\s*(?:은|는|:|=)|status|표시명|"
    r"db_key|같은\s+(?:필터\s+)?표현|같은\s+의미)"
)


def _format_refined_text(text: str) -> str:
    """읽기 어려운 LLM 한 줄 출력을 의미 변경 없이 여러 줄로 정리합니다."""

    original = str(text or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not original:
        return ""

    protected, sql_blocks, sql_was_reformatted = _protect_inline_sql(original)
    nonempty_lines = [line for line in protected.splitlines() if line.strip()]
    sentence_count = len(_SENTENCE_BOUNDARY.split(" ".join(nonempty_lines)))
    has_compact_sql_line = any(
        re.match(r"(?i)^(?:SELECT|WITH)\b", line.strip())
        and re.search(r"(?i)\s(?:FROM|WHERE|JOIN|GROUP\s+BY|ORDER\s+BY)\s", line)
        for line in nonempty_lines
    )
    needs_prose_format = (
        any(len(line) > 140 for line in nonempty_lines)
        or (len(nonempty_lines) == 1 and sentence_count >= 3)
        or has_compact_sql_line
    )

    if needs_prose_format:
        paragraphs = re.split(r"\n\s*\n", protected)
        protected = "\n\n".join(
            formatted
            for paragraph in paragraphs
            if (formatted := _format_prose_paragraph(paragraph))
        )

    for marker, sql in sql_blocks:
        protected = protected.replace(marker, sql)

    if not needs_prose_format and not sql_was_reformatted:
        return original
    return _normalize_blank_lines(protected)


def _protect_inline_sql(text: str) -> tuple[str, list[tuple[str, str]], bool]:
    blocks: list[tuple[str, str]] = []

    def replace_fence(match: re.Match[str]) -> str:
        marker = f"<<<METADATA_REFINED_SQL_{len(blocks)}>>>"
        blocks.append((marker, _format_sql(match.group("sql"))))
        return f"\n\n{marker}\n\n"

    def replace(match: re.Match[str]) -> str:
        marker = f"<<<METADATA_REFINED_SQL_{len(blocks)}>>>"
        label = str(match.group("label") or "조회 SQL은").strip()
        ending = str(match.group("ending") or "").strip()
        if ending == "입니다":
            introduction = f"{label} 아래와 같습니다."
        elif ending in {"야", "이야", "예요"}:
            introduction = f"{label} 아래와 같아."
        else:
            introduction = f"{label} 아래와 같다."
        block = f"{introduction}\n\n{_format_sql(match.group('sql'))}"
        blocks.append((marker, block))
        return f"\n\n{marker}\n\n"

    protected = _FENCED_SQL.sub(replace_fence, text)
    protected = _INLINE_QUOTED_SQL.sub(replace, protected)
    protected = _INLINE_UNQUOTED_SQL.sub(replace, protected)
    return protected, blocks, bool(blocks)


def _format_sql(value: Any) -> str:
    sql = str(value or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not sql:
        return ""

    protected_segments: list[str] = []

    def protect_segment(match: re.Match[str]) -> str:
        marker = f"<<<SQL_PROTECTED_{len(protected_segments)}>>>"
        protected_segments.append(match.group(0))
        return marker

    protected = _SQL_PROTECTED_SEGMENT.sub(protect_segment, sql)
    clauses = (
        r"LEFT\s+OUTER\s+JOIN",
        r"RIGHT\s+OUTER\s+JOIN",
        r"FULL\s+OUTER\s+JOIN",
        r"LEFT\s+JOIN",
        r"RIGHT\s+JOIN",
        r"FULL\s+JOIN",
        r"INNER\s+JOIN",
        r"CROSS\s+JOIN",
        r"GROUP\s+BY",
        r"ORDER\s+BY",
        r"UNION\s+ALL",
        r"UNION",
        r"FROM",
        r"WHERE",
        r"HAVING",
        r"LIMIT",
        r"OFFSET",
    )
    protected = re.sub(
        rf"[ \t]+(?=(?:{'|'.join(clauses)})\b)",
        "\n",
        protected,
        flags=re.IGNORECASE,
    )
    protected = re.sub(r"(?i)^SELECT[ \t]+", "SELECT\n    ", protected)
    protected = re.sub(r"(?i)^WITH[ \t]+", "WITH\n    ", protected)
    for index, segment in enumerate(protected_segments):
        protected = protected.replace(f"<<<SQL_PROTECTED_{index}>>>", segment)
    return "\n".join(line.rstrip() for line in protected.splitlines()).strip()


def _format_prose_paragraph(paragraph: str) -> str:
    lines = [line.strip() for line in str(paragraph or "").splitlines() if line.strip()]
    if not lines:
        return ""
    if re.match(r"(?i)^(?:SELECT|WITH)\b", " ".join(lines)):
        return _format_sql(" ".join(lines))
    if len(lines) > 1:
        formatted_lines: list[str] = []
        for line in lines:
            parts = _format_content_line(line)
            if formatted_lines and parts and re.match(r"(?i)^(?:SELECT|WITH)\b", parts[0]):
                formatted_lines.append("")
            formatted_lines.extend(parts)
        return "\n".join(formatted_lines)

    sentences = [item.strip() for item in _SENTENCE_BOUNDARY.split(lines[0]) if item.strip()]
    if len(sentences) <= 1:
        return "\n".join(_wrap_long_line(lines[0]))

    groups: list[list[str]] = []
    current_group: list[str] = []
    current_kind = ""
    for index, sentence in enumerate(sentences):
        kind = _prose_group(sentence, index)
        if current_group and kind != current_kind:
            groups.append(current_group)
            current_group = []
        current_group.extend(_format_content_line(sentence))
        current_kind = kind
    if current_group:
        groups.append(current_group)
    return "\n\n".join("\n".join(group) for group in groups)


def _prose_group(sentence: str, index: int) -> str:
    compact = str(sentence or "").strip()
    if index == 0 and "등록" in compact and "메타데이터" in compact:
        return "registration"
    if _IDENTITY_SENTENCE.search(compact):
        return "identity"
    return "details"


def _wrap_long_line(line: str) -> list[str]:
    value = str(line or "").strip()
    if len(value) <= 140 or value.startswith("<<<METADATA_REFINED_SQL_"):
        return [value]
    return textwrap.wrap(
        value,
        width=120,
        break_long_words=False,
        break_on_hyphens=False,
        replace_whitespace=False,
        drop_whitespace=True,
    ) or [value]


def _format_content_line(line: str) -> list[str]:
    value = str(line or "").strip()
    if re.match(r"(?i)^(?:SELECT|WITH)\b", value):
        return _format_sql(value).splitlines()
    return _wrap_long_line(value)


def _normalize_blank_lines(text: str) -> str:
    lines = [line.rstrip() for line in str(text or "").splitlines()]
    result: list[str] = []
    previous_blank = False
    for line in lines:
        blank = not line.strip()
        if blank and (previous_blank or not result):
            continue
        result.append("" if blank else line)
        previous_blank = blank
    while result and not result[-1]:
        result.pop()
    return "\n".join(result).strip()


def _contains_unapproved_target(
    text: str,
    unresolved: list[dict[str, Any]],
    errors: list[dict[str, Any]],
) -> bool:
    targets: list[str] = []
    for item in unresolved:
        targets.extend(_string_list(item.get("candidates")))
        targets.extend(
            str(item.get(field) or "").strip()
            for field in ("target", "suggested_target")
            if str(item.get(field) or "").strip()
        )
    for error in errors:
        targets.extend(_string_list(error.get("candidates")))
        targets.extend(
            str(error.get(field) or "").strip()
            for field in ("target", "registered_target")
            if str(error.get(field) or "").strip()
        )
    return any(_text_contains_target(text, target) for target in _unique_text(targets))


def _text_contains_target(text: str, target: str) -> bool:
    key = str(target or "").strip()
    if not key:
        return False
    if re.fullmatch(r"[A-Za-z0-9_.:-]+", key):
        return bool(re.search(rf"(?<![A-Za-z0-9_]){re.escape(key)}(?![A-Za-z0-9_])", text, flags=re.IGNORECASE))
    return _compact(key) in _compact(text)


def _dedupe_references(values: list[dict[str, Any]]) -> list[dict[str, Any]]:
    result = []
    seen = set()
    for item in values:
        marker = (item.get("kind"), _compact(item.get("input")), str(item.get("target") or "").casefold())
        if marker not in seen:
            seen.add(marker)
            result.append(item)
    return result


def _json_object(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        return deepcopy(value)
    text = str(getattr(value, "text", value) or "").strip()
    fenced = re.search(r"```(?:json)?\s*(\{.*?\})\s*```", text, re.DOTALL | re.IGNORECASE)
    if fenced:
        text = fenced.group(1)
    try:
        parsed = json.loads(text)
    except Exception:
        return {}
    return parsed if isinstance(parsed, dict) else {}


def _compact(value: Any) -> str:
    normalized = unicodedata.normalize("NFKC", str(value or "")).casefold()
    return re.sub(r"[^0-9a-z가-힣]+", "", normalized)


def _tokens(value: Any) -> list[str]:
    stop = {"등록", "저장", "정보", "내용", "관련", "사용", "데이터", "데이터셋", "테이블", "컬럼", "조건"}
    separated = re.sub(
        r"(?<=[A-Za-z0-9_])(?=[가-힣])|(?<=[가-힣])(?=[A-Za-z0-9_])",
        " ",
        str(value or ""),
    )
    return [
        token
        for token in (_compact(item) for item in re.findall(r"[가-힣A-Za-z0-9_]+", separated))
        if len(token) >= 2 and token not in stop
    ]


def _unique_text(values: Any) -> list[str]:
    result = []
    seen = set()
    for value in values if isinstance(values, (list, tuple, set)) else []:
        text = str(value or "").strip()
        if text and text not in seen:
            seen.add(text)
            result.append(text)
    return result


def _string_list(value: Any) -> list[str]:
    return [str(item).strip() for item in value if str(item or "").strip()] if isinstance(value, list) else []


def _truthy(value: Any) -> bool:
    return value is True or str(value or "").strip().lower() in {"1", "true", "yes", "y", "on"}


def _payload(value: Any) -> dict[str, Any]:
    data = getattr(value, "data", value)
    return deepcopy(data) if isinstance(data, dict) else {}


def _dict(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


class MetadataAuthoringRefinementNormalizerRev2(Component):
    display_name = "04 메타데이터 등록 정제 결과 검증기 rev_2"
    description = "정제 LLM의 참조를 활성 metadata registry와 대조하고 원문과 분리된 정제안을 만듭니다."
    inputs = [
        DataInput(name="payload", display_name="Context 페이로드", required=True),
